def comps(val, diag=True):
 seen=set(); result=[]
 dirs=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
 for r,c in zip(*np.where(A==val)):
  if (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   x=q.pop();comp.append(x)
   for dr,dc in dirs:
    p=x[0]+dr,x[1]+dc
    if 0<=p[0]<30 and 0<=p[1]<30 and p not in seen and A[p]==val:
     seen.add(p);q.append(p)
  result.append(comp)
 return result
