def adjcomps_to_color(target, val, diag=True):
 cs=comps(val,diag)
 dirs=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
 for i,cp in enumerate(cs):
  adj=set()
  for r,c in cp:
   for dr,dc in dirs:
    x,y=r+dr,c+dc
    if 0<=x<30 and 0<=y<30 and A[x,y]==target: adj.add((x,y))
